echo "    public function index() {<br>";
echo "        return view('welcome');<br>";
echo "    }<br>";
echo "}<br><br>";

echo "=== Routing ===<br>";
echo "// app/Config/Routes.php<br>";
echo "$routes->get('/', 'Home::index');<br>";
