            }
        }
        console.log();
    }
}

// Assertions
function expect(actual) {
    return {
        toBe(expected) {
            if (actual !== expected) {
                throw new Error();
            }
        },
        toEqual(expected) {
            if (JSON.stringify(actual) !== JSON.stringify(expected)) {
                throw new Error();
            }
        },
        toBeGreaterThan(n) {
            if (actual <= n) {
                throw new Error();
            }
        },
        toContain(item) {
            if (!actual.includes(item)) {
                throw new Error();
            }
        },
        toThrow(fn) {
            try { fn(); }
            catch { return; }
            throw new Error("Expected function to throw");
        }
    };
}

// Test subject
function add(a, b) { return a b; }
