Object-Oriented Programming
from abc import ABC, abstractmethod

class BankAccount:
    """Rekening bank dengan OOP."""
    bank_name = "Python Bank"

    def _init_(self, owner: str, balance: float = 0):
        self.owner = owner
        self._balance = balance
        self.__id = id(self)

    def deposit(self, amount: float):
        if amount <= 0:
            raise ValueError("Jumlah deposit harus positif")
        self._balance += amount
        return self

    def withdraw(self, amount: float):
        if amount > self._balance:
            raise ValueError("Saldo tidak cukup")
        self._balance -= amount
        return self

    @property
    def balance(self):
        return self._balance

    def _str_(self):
        return f"{self.owner}: Rp{self._balance:,.0f}"

    def _repr_(self):
        return f"BankAccount('{self.owner}', {self._balance})"

class SavingsAccount(BankAccount):
    """Rekening tabungan dengan bunga."""

    def _init_(self, owner: str, balance: float = 0, rate: float = 0.05):
        super()._init_(owner, balance)
        self.rate = rate

    def add_interest(self):
        interest = self._balance self.rate
        self._balance += interest
        return interest

class Shape(ABC):
    @abstractmethod
    def area(self): pass

    @abstractmethod
    def perimeter(self): pass

class Rectangle(Shape):
    def _init_(self, width, height):
        self.width = width
        self.height = height

    def area(self): return self.width self.height
    def perimeter(self): return 2 (self.width self.height)
    def _str_(self): return f"Rectangle({self.width}x{self.height})"

